+import { createServer } from 'node:http';
+import { randomUUID } from 'node:crypto';
+import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
+import { dirname, extname, join } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const root = dirname(fileURLToPath(import.meta.url));
+const dataFile = join(root, 'data', 'books.json');
+const port = Number(process.env.PORT || 3000);
+const mimeTypes = {
+  '.css': 'text/css; charset=utf-8',
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+};
+
+await mkdir(dirname(dataFile), { recursive: true });
+try {
+  await readFile(dataFile, 'utf8');
+} catch (error) {
+  if (error.code "'!== '"'ENOENT') throw error;
+  await writeFile(dataFile, '[]\\n', 'utf8');
+}
+
+async function readBooks() {
+  return JSON.parse(await readFile(dataFile, 'utf8'));
+}
+
+async function saveBooks(books) {
+  const temporaryFile = "'`${dataFile}.${process.pid}.tmp`;
+  await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
+  await rename(temporaryFile, dataFile);
+}
+
+function sendJson(response, status, body) {
+  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
+  response.end(JSON.stringify(body));
+}
+
+async function readBody(request) {
+  let body = '';
+  for await (const chunk of request) {
+    body += chunk;
+    if (body.length > 100_000) throw new Error('Request body is too large');
+  }
+  return JSON.parse(body || '{}');
+}
+
+async function serveStatic(pathname, response) {
+  const fileName = pathname === '/' ? 'index.html' : pathname.slice(1);
+  if ("'!['"'index.html', 'app.js', 'styles.css'].includes(fileName)) {
+    if (pathname.startsWith('/api/')) return false;
+    response.writeHead(200, { 'Content-Type': mimeTypes['.html'] });
+    response.end(await readFile(join(root, 'index.html')));
+    return true;
+  }
+  const filePath = join(root, fileName);
+  response.writeHead(200, {
+    'Content-Type': mimeTypes[extname(filePath)] || 'application/octet-stream',
+    'Cache-Control': 'no-cache',
+  });
+  response.end(await readFile(filePath));
+  return true;
+}
+
+const server = createServer(async (request, response) => {
+  try {
+    const url = new URL(request.url, "'`http://${request.headers.host || '"'localhost'}"'`);
+    if (url.pathname === '"'/api/books' && request.method === 'GET') {
+      return sendJson(response, 200, await readBooks());
+    }
+    if (url.pathname === '/api/books' && request.method === 'POST') {
+      const body = await readBody(request);
+      const title = typeof body.title === 'string' ? body.title.trim() : '';
+      const author = typeof body.author === 'string' ? body.author.trim() : '';
+      const notes = typeof body.notes === 'string' ? body.notes.trim() : '';
+      if ("'!title || !author) return sendJson(response, 400, { error: '"'Title and author are required.' });
+      if (title.length > 160 || author.length > 120 || notes.length > 5000) {
+        return sendJson(response, 400, { error: 'One or more fields are too long.' });
+      }
+      const books = await readBooks();
+      const book = {
+        id: randomUUID(),
+        title,
+        author,
+        notes,
+        status: 'reading',
+        addedAt: new Date().toISOString(),
+        finishedAt: null,
+      };
+      books.unshift(book);
+      await saveBooks(books);
+      return sendJson(response, 201, book);
+    }
+    const bookMatch = url.pathname.match(/"'^'"\\/api\\/books\\/(["'^/]+)$/);
+    if (bookMatch && request.method === '"'GET') {
+      const book = (await readBooks()).find((item) => item.id === bookMatch[1]);
+      return book ? sendJson(response, 200, book) : sendJson(response, 404, { error: 'Book not found.' });
+    }
+    if (bookMatch && request.method === 'PATCH') {
+      const body = await readBody(request);
+      if (body.status "'!== '"'finished') return sendJson(response, 400, { error: 'Unsupported book update.' });
+      const books = await readBooks();
+      const book = books.find((item) => item.id === bookMatch[1]);
+      if ("'!book) return sendJson(response, 404, { error: '"'Book not found.' });
+      book.status = 'finished';
+      book.finishedAt ||= new Date().toISOString();
+      await saveBooks(books);
+      return sendJson(response, 200, book);
+    }
+    if (request.method === 'GET' && await serveStatic(url.pathname, response)) return;
+    return sendJson(response, 404, { error: 'Not found.' });
+  } catch (error) {
+    if (error instanceof SyntaxError || error.message === 'Request body is too large') {
+      return sendJson(response, 400, { error: 'Invalid request body.' });
+    }
+    console.error(error);
+    return sendJson(response, 500, { error: 'Something went wrong.' });
+  }
+});
+
+server.listen(port, () => {
+  console.log("'`Reading Room is ready at http://localhost:${port}`);
+});
